using System.Collections.Generic;
using UnityEngine;

namespace VerdantSiege.Visual
{
    /// <summary>
    /// The Sanctuary diorama's restoration (Milestone 4, GDD 12.1: "as the player restores regions, the sanctuary
    /// visibly becomes greener, brighter and more populated"). Tier 0 is blighted (rot, grey haze); each tier adds a
    /// group of props generated by the scene builder, and the light warms up. A newly reached tier grows in.
    /// Presentation only: the tier comes from CampaignRules.SanctuaryTier.
    /// </summary>
    public sealed class SanctuaryRestoration : MonoBehaviour
    {
        [Tooltip("Rot and dead dressing shown below tier 2.")]
        public GameObject blight;
        [Tooltip("Groups enabled at tiers 1..4.")]
        public GameObject[] tiers = new GameObject[4];
        public Light sun;
        public Camera view;

        private static readonly Color SkyBlighted = new Color(0.55f, 0.56f, 0.62f), SkyLush = new Color(0.62f, 0.7f, 0.78f);
        private static readonly Color EquatorBlighted = new Color(0.4f, 0.38f, 0.42f), EquatorLush = new Color(0.46f, 0.57f, 0.42f);
        private static readonly Color GroundBlighted = new Color(0.2f, 0.18f, 0.2f), GroundLush = new Color(0.24f, 0.29f, 0.16f);
        private static readonly Color FogBlighted = new Color(0.6f, 0.58f, 0.66f), FogLush = new Color(0.68f, 0.84f, 0.76f);
        private static readonly Color BgBlighted = new Color(0.58f, 0.6f, 0.68f), BgLush = new Color(0.6f, 0.8f, 0.88f);

        private readonly List<(Transform t, Vector3 scale)> _growing = new List<(Transform, Vector3)>();
        private float _growT = -1f;
        private int _tier;

        public int Tier => _tier;

        /// <summary>Shows the dressing and light for a tier immediately.</summary>
        public void Apply(int tier)
        {
            _tier = Mathf.Clamp(tier, 0, tiers.Length);
            if (blight != null) blight.SetActive(_tier < 2);
            for (int i = 0; i < tiers.Length; i++) if (tiers[i] != null) tiers[i].SetActive(_tier >= i + 1);
            float k = _tier / (float)Mathf.Max(1, tiers.Length);
            RenderSettings.ambientSkyColor = Color.Lerp(SkyBlighted, SkyLush, k);
            RenderSettings.ambientEquatorColor = Color.Lerp(EquatorBlighted, EquatorLush, k);
            RenderSettings.ambientGroundColor = Color.Lerp(GroundBlighted, GroundLush, k);
            RenderSettings.fogColor = Color.Lerp(FogBlighted, FogLush, k);
            if (view != null) view.backgroundColor = Color.Lerp(BgBlighted, BgLush, k);
            if (sun != null)
            {
                sun.intensity = Mathf.Lerp(0.95f, 1.35f, k);
                sun.color = Color.Lerp(new Color(0.88f, 0.86f, 0.9f), new Color(1f, 0.92f, 0.76f), k);
            }
        }

        /// <summary>Restores from <paramref name="from"/> to <paramref name="to"/>: the new groups grow out of the ground.</summary>
        public void Celebrate(int from, int to)
        {
            Apply(to);
            _growing.Clear();
            for (int i = Mathf.Max(0, from); i < Mathf.Min(to, tiers.Length); i++)
            {
                if (tiers[i] == null) continue;
                foreach (Transform c in tiers[i].transform)
                {
                    _growing.Add((c, c.localScale));
                    c.localScale = Vector3.zero;
                }
            }
            _growT = 0f;
        }

        private void Update()
        {
            if (_growT < 0f) return;
            _growT += Time.deltaTime;
            bool done = true;
            for (int i = 0; i < _growing.Count; i++)
            {
                (Transform t, Vector3 s) = _growing[i];
                if (t == null) continue;
                float local = Mathf.Clamp01((_growT - (i % 12) * 0.08f) / 0.9f);
                float e = 1f + 2.2f * Mathf.Pow(local - 1f, 3f) + 1.2f * Mathf.Pow(local - 1f, 2f); // overshoot ease
                t.localScale = s * Mathf.Max(0f, e);
                if (local < 1f) done = false;
            }
            if (done) { _growT = -1f; foreach ((Transform t, Vector3 s) in _growing) if (t != null) t.localScale = s; }
        }
    }
}
